class Solution {
public:
    int best = 0;
    vector<int> masks;
    void go(vector<string>& arr, int i, int mask, int len) {
        best = max(best, len);
        if (i == (int)arr.size()) return;
        if (masks[i] >= 0 && (mask & masks[i]) == 0) go(arr, i + 1, mask | masks[i], len + arr[i].size());
        go(arr, i + 1, mask, len);
    }
    int maxLength(vector<string>& arr) {
        for (auto& w : arr) {
            int m = 0;
            for (char c : w) {
                if (m & (1 << (c - 'a'))) {
                    m = -1;
                    break;
                }
                m |= 1 << (c - 'a');
            }
            masks.push_back(m);
        }
        go(arr, 0, 0, 0);
        return best;
    }
};
